def extract_output_text(payload: Any) -> str:
    """Concatenate every ``output_text`` part of a Responses API payload."""
    if not isinstance(payload, dict):
        return ""
    chunks: List[str] = []
    for item in payload.get("output") or []:
        if not isinstance(item, dict) or item.get("type") != "message":
            continue
        if item.get("role") not in (None, "assistant"):
            continue
        for part in item.get("content") or []:
            if not isinstance(part, dict):
                continue
            if part.get("type") in ("output_text", "text"):
                text = part.get("text")
                if isinstance(text, str):
                    chunks.append(text)
    return "".join(chunks)


def _as_int(value: Any) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0


def _normalize_input(value: Input) -> List[InputItem]:
    """Convert a prompt, an item, or a sequence of either into input items."""
    if value is None:
        raise ConfigurationError("input is required")
    if isinstance(value, str):
        if not value.strip():
            raise ConfigurationError("input prompt is empty")
        return [{"type": "message", "role": "user", "content": value}]
    if isinstance(value, dict):
        return [value]
    if isinstance(value, (list, tuple)):
        items: List[InputItem] = []
        for element in value:
            items.extend(_normalize_input(element))
        return items
    raise ConfigurationError(f"unsupported input type: {type(value).__name__}")


def _assistant_item(response_payload: Any, fallback_text: str = "") -> Optional[InputItem]:
    """Build a replayable assistant message item from a response payload."""
    if isinstance(response_payload, dict):
        for item in response_payload.get("output") or []:
            if not isinstance(item, dict) or item.get("type") != "message":
                continue
            if item.get("role") != "assistant":
                continue
            content = [
                {"type": "output_text", "text": part.get("text", "")}
                for part in (item.get("content") or [])
                if isinstance(part, dict) and part.get("type") in ("output_text", "text")
            ]
            if content:
                return {"type": "message", "role": "assistant", "content": content}
    if fallback_text:
        return {
            "type": "message",
            "role": "assistant",
            "content": [{"type": "output_text", "text": fallback_text}],
        }
    return None


def _read_body(stream: Any) -> str:
    try:
        raw = stream.read(_MAX_ERROR_BODY_BYTES)
    except (OSError, http.client.HTTPException):
        return ""
    finally:
        try:
            stream.close()
        except Exception:
            pass
    if isinstance(raw, bytes):
        return raw.decode("utf-8", errors="replace")
    return raw or ""


def _status_error(status_code: int, headers: Any, body_text: str) -> APIStatusError:
    message = body_text.strip() or f"request failed with HTTP {status_code}"
    error_type = code = param = None
    parsed: Any = None
    try:
        parsed = json.loads(body_text) if body_text else None
    except ValueError:
        parsed = None
    if isinstance(parsed, dict):
        error = parsed.get("error")
        if isinstance(error, dict):
            message = str(error.get("message") or message)
            error_type = error.get("type")
            code = error.get("code")
            param = error.get("param")
    if status_code in (401, 403):
        message += " -- check that OPENAI_API_KEY is set and valid for this endpoint"
    request_id = None
    if headers:
        request_id = headers.get("x-request-id") or headers.get("X-Request-Id")
    return APIStatusError(
        message,
        status_code=status_code,
        error_type=error_type,
        code=code,
        param=param,
        request_id=request_id,
        body=parsed if parsed is not None else body_text,
    )


def _retry_after_seconds(headers: Any) -> Optional[float]:
    if not headers:
        return None
    value = headers.get("Retry-After") or headers.get("retry-after")
    if not value:
        return None
    try:
        return max(0.0, float(value))
    except ValueError:
        pass
    try:
        when = parsedate_to_datetime(value)
    except (TypeError, ValueError):
        return None
    if when is None:
        return None
    return max(0.0, when.timestamp() - time.time())


def _iter_sse(stream: Any) -> Iterator[Any]:
    """Yield ``(event_name, data_text)`` pairs from a Server-Sent Event stream."""
    event_name: Optional[str] = None
    data_lines: List[str] = []
    for raw_line in stream:
        line = raw_line.decode("utf-8", errors="replace") if isinstance(raw_line, bytes) else str(raw_line)
        line = line.rstrip("'"\\r\\n\")
        if not line:
            if data_lines:
                yield event_name or \"message\", \"\\n\".join(data_lines)
            event_name, data_lines = None, []
            continue
        if line.startswith(\":\"):
            continue
        name, _, value = line.partition(\":\")
        if value.startswith(\" \"):
            value = value[1:]
        if name == \"event\":
            event_name = value
        elif name == \"data\":
            data_lines.append(value)
    if data_lines:
        yield event_name or \"message\", \"\\n\".join(data_lines)


class OpenAIClient:
    \"\"\"Minimal Responses API client built on :mod:"'`urllib.request`.

    Instances are cheap and reusable; they hold no prompt data.
    """

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        base_url: Optional[str] = None,
        model: Optional[str] = None,
        timeout: float = DEFAULT_TIMEOUT,
        max_retries: int = DEFAULT_MAX_RETRIES,
        store: bool = False,
        organization: Optional[str] = None,
        project: Optional[str] = None,
        default_headers: Optional[Dict[str, str]] = None,
        proxy: Union[str, bool, None] = None,
        verify_tls: bool = True,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY") or ""
        if not self.api_key:
            raise ConfigurationError(
                "no API key: set OPENAI_API_KEY or pass api_key=... "
                "(the key is never written to disk by this module)"
            )
        self.base_url = (
            base_url or os.environ.get("OPENAI_BASE_URL") or DEFAULT_BASE_URL
        ).rstrip("/")
        self.model = model or os.environ.get("OPENAI_MODEL") or DEFAULT_MODEL
        self.timeout = float(timeout)
        self.max_retries = max(0, int(max_retries))
        self.store = bool(store)

        headers: Dict[str, str] = {"User-Agent": USER_AGENT}
        org = organization or os.environ.get("OPENAI_ORG_ID")
        if org:
            headers["OpenAI-Organization"] = org
        project_id = project or os.environ.get("OPENAI_PROJECT_ID")
        if project_id:
            headers["OpenAI-Project"] = project_id
        if default_headers:
            headers.update(default_headers)
        self.default_headers = headers

        if verify_tls:
            ssl_context = ssl.create_default_context()
        else:
            warnings.warn(
                "TLS verification disabled; traffic to the API can be intercepted",
                RuntimeWarning,
                stacklevel=2,
            )
            ssl_context = ssl._create_unverified_context()

        handlers: List[Any] = [urllib.request.HTTPSHandler(context=ssl_context)]
        if proxy is False:
            handlers.append(urllib.request.ProxyHandler({}))
        elif isinstance(proxy, str) and proxy:
            handlers.append(urllib.request.ProxyHandler({"http": proxy, "https": proxy}))
        self._opener = urllib.request.build_opener(*handlers)
        self._opener.addheaders = []

    @property
    def responses_url(self) -> str:
        return f"{self.base_url}/responses"

    def build_payload(
        self,
        input: Input,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        stream: bool = False,
        store: Optional[bool] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        reasoning_effort: Optional[str] = None,
        reasoning: Optional[Dict[str, Any]] = None,
        text: Optional[Dict[str, Any]] = None,
        previous_response_id: Optional[str] = None,
        metadata: Optional[Dict[str, str]] = None,
        prompt_cache_key: Optional[str] = None,
        safety_identifier: Optional[str] = None,
        tools: Optional[Sequence[Dict[str, Any]]] = None,
        extra_body: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Assemble and validate a request body without sending it."""
        use_store = self.store if store is None else bool(store)
        if previous_response_id and not use_store:
            raise ConfigurationError(
                "previous_response_id requires stored responses; either pass "
                "store=True or replay the conversation with Conversation()"
            )

        payload: Dict[str, Any] = {
            "model": model or self.model,
            "input": _normalize_input(input),
            "store": use_store,
        }
        if stream:
            payload["stream"] = True
        if instructions:
            payload["instructions"] = instructions
        if temperature is not None:
            payload["temperature"] = float(temperature)
        if max_output_tokens is not None:
            payload["max_output_tokens"] = int(max_output_tokens)
        reasoning_config = dict(reasoning or {})
        if reasoning_effort:
            reasoning_config["effort"] = reasoning_effort
        if reasoning_config:
            payload["reasoning"] = reasoning_config
        if text is not None:
            payload["text"] = text
        if previous_response_id:
            payload["previous_response_id"] = previous_response_id
        if metadata:
            payload["metadata"] = {str(key): str(value) for key, value in metadata.items()}
        if prompt_cache_key:
            payload["prompt_cache_key"] = prompt_cache_key
        if safety_identifier:
            payload["safety_identifier"] = safety_identifier
        if tools:
            payload["tools"] = list(tools)
        if extra_body:
            payload.update(extra_body)
        return payload

    def _prepare(self, payload: Dict[str, Any]) -> urllib.request.Request:
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        headers = dict(self.default_headers)
        headers["Content-Type"] = "application/json"
        headers["Accept"] = "text/event-stream" if payload.get("stream") else "application/json"
        headers["Authorization"] = f"Bearer {self.api_key}"
        return urllib.request.Request(self.responses_url, data=body, headers=headers, method="POST")

    def _open(self, payload: Dict[str, Any]) -> Any:
        """Send ``payload`` with retries, returning an open HTTP response."""
        attempt = 0
        while True:
            request = self._prepare(payload)
            try:
                return self._opener.open(request, timeout=self.timeout)
            except urllib.error.HTTPError as exc:
                body_text = _read_body(exc)
                if exc.code in RETRYABLE_STATUS_CODES and attempt < self.max_retries:
                    delay = _retry_after_seconds(exc.headers)
                    self._sleep(delay, attempt)
                    attempt += 1
                    continue
                raise _status_error(exc.code, exc.headers, body_text) from None
            except socket.timeout as exc:
                if attempt < self.max_retries:
                    self._sleep(None, attempt)
                    attempt += 1
                    continue
                raise APITimeoutError(f"timed out after {self.timeout:g}s") from exc
            except (urllib.error.URLError, TimeoutError, ConnectionError, OSError, http.client.HTTPException) as exc:
                if isinstance(exc, urllib.error.HTTPError):
                    raise
                reason = getattr(exc, "reason", exc)
                if isinstance(reason, socket.timeout):
                    if attempt < self.max_retries:
                        self._sleep(None, attempt)
                        attempt += 1
                        continue
                    raise APITimeoutError(f"timed out after {self.timeout:g}s") from exc
                if attempt < self.max_retries:
                    self._sleep(None, attempt)
                    attempt += 1
                    continue
                raise APIConnectionError(f"could not reach {self.base_url}: {reason}") from exc

    def _sleep(self, retry_after: Optional[float], attempt: int) -> None:
        delay = retry_after if retry_after is not None else min(8.0, 0.5 * (2**attempt))
        time.sleep(max(0.0, delay))

    def post_responses(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Low-level escape hatch: send a raw payload, get raw JSON back."""
        payload = dict(payload)
        payload.pop("stream", None)
        stream = self._open(payload)
        try:
            body = _read_body(stream)
        finally:
            try:
                stream.close()
            except Exception:
                pass
        try:
            data = json.loads(body)
        except ValueError as exc:
            raise APIConnectionError(f"malformed JSON response: {body[:200]!r}") from exc
        if not isinstance(data, dict):
            raise APIConnectionError("unexpected response shape")
        return data

    def create(self, input: Input, **params: Any) -> Response:
        """Send one non-streaming request and return a parsed :class:`Response`."""
        params.pop("stream", None)
        payload = self.build_payload(input, stream=False, **params)
        return Response.from_payload(self.post_responses(payload))

    def complete(self, prompt: str, **params: Any) -> str:
        """Send a private text prompt and return the assistant'"'s text.\"\"\"
        return self.create(prompt, **params).raise_for_status().text

    def stream(self, input: Input, **params: Any) -> Iterator[StreamEvent]:
        \"\"\"Yield :class:"'`StreamEvent` objects for a streaming request."""
        payload = self.build_payload(input, stream=True, **params)
        stream = self._open(payload)
        try:
            for event_name, data_text in _iter_sse(stream):
                if data_text.strip() == "[DONE]":
                    break
                try:
                    data = json.loads(data_text)
                except ValueError:
                    continue
                if not isinstance(data, dict):
                    continue
                event_type = str(data.get("type") or event_name)
                yield StreamEvent(type=event_type, event=event_name, data=data)
                if event_type in TERMINAL_STREAM_EVENTS:
                    if event_type == "error":
                        error = data.get("error") or data
                        raise APIStatusError(
                            str(error.get("message") or "stream failed"),
                            error_type=error.get("type"),
                            code=error.get("code"),
                            body=data,
                        )
                    break
        finally:
            try:
                stream.close()
            except Exception:
                pass

    def stream_text(self, input: Input, **params: Any) -> Iterator[str]:
        """Yield only the incremental output text of a streaming request."""
        for event in self.stream(input, **params):
            if event.type == "response.output_text.delta" and event.delta:
                yield event.delta

    def list_models(self, limit: int = 100) -> List[Dict[str, Any]]:
        """Fetch model ids (useful to check credentials without sending a prompt)."""
        request = urllib.request.Request(
            f"{self.base_url}/models?limit={int(limit)}",
            headers=dict(self.default_headers, Accept="application/json", Authorization=f"Bearer {self.api_key}"),
            method="GET",
        )
        try:
            with self._opener.open(request, timeout=self.timeout) as stream:
                body = _read_body(stream)
        except urllib.error.HTTPError as exc:
            raise _status_error(exc.code, exc.headers, _read_body(exc)) from None
        except (urllib.error.URLError, socket.timeout, TimeoutError, ConnectionError, OSError) as exc:
            raise APIConnectionError(f"could not reach {self.base_url}: {getattr(exc, '"'reason', exc)}\") from exc
        try:
            data = json.loads(body)
        except ValueError as exc:
            raise APIConnectionError(f\"malformed JSON response: {body[:200]"'!r}") from exc
        models = data.get("data") if isinstance(data, dict) else None
        return [item for item in (models or []) if isinstance(item, dict)]


class Conversation:
    """In-memory multi-turn chat that never relies on server-side storage.

    Because private requests use ``store=False`` there is no
    ``previous_response_id`` to chain; this class replays the transcript from
    process memory instead.  Nothing is written to disk and the transcript dies
    with the process (call :meth:`clear` to drop it earlier).
    """

    def __init__(
        self,
        client: Optional[OpenAIClient] = None,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        store: bool = False,
        max_turns: Optional[int] = None,
    ) -> None:
        self.client = client or OpenAIClient()
        self.model = model
        self.instructions = instructions
        self.store = store
        self.max_turns = max_turns
        self.items: List[InputItem] = []
        self.last_usage: Usage = Usage()
        self.last_response_id: str = ""

    def send(self, prompt: str, **params: Any) -> str:
        """Send ``prompt`` with the remembered transcript; return reply text."""
        response = self._request(prompt, stream=False, **params)
        self.last_usage = response.usage
        self.last_response_id = response.id
        self._record_user(prompt)
        item = _assistant_item(response.raw)
        if item:
            self._record(item)
        response.raise_for_status()
        return response.text

    def stream(self, prompt: str, **params: Any) -> Iterator[str]:
        """Stream the reply for ``prompt`` as text deltas, recording the turn."""
        self._record_user(prompt)
        collected: List[str] = []
        final_payload: Any = None
        try:
            for event in self._events(prompt, **params):
                if event.type == "response.output_text.delta" and event.delta:
                    collected.append(event.delta)
                    yield event.delta
                elif event.type in ("response.completed", "response.incomplete"):
                    final_payload = event.data.get("response")
        finally:
            payload = final_payload if isinstance(final_payload, dict) else None
            if payload:
                self.last_usage = Usage.from_payload(payload.get("usage"))
                self.last_response_id = str(payload.get("id") or "")
            item = _assistant_item(payload, "".join(collected))
            if item:
                self._record(item)

    def events(self, prompt: str, **params: Any) -> Iterator[StreamEvent]:
        """Stream every SSE event for ``prompt`` without recording the turn."""
        return self._events(prompt, **params)

    @property
    def transcript(self) -> List[InputItem]:
        """A copy of the in-memory conversation items."""
        return [json.loads(json.dumps(item)) for item in self.items]

    def clear(self) -> None:
        """Forget the transcript and per-turn accounting."""
        self.items.clear()
        self.last_usage = Usage()
        self.last_response_id = ""

    def _events(self, prompt: str, **params: Any) -> Iterator[StreamEvent]:
        payload_input = self._input_with(prompt)
        return self.client.stream(
            payload_input,
            model=self.model or params.pop("model", None),
            instructions=params.pop("instructions", None) or self.instructions,
            store=self.store,
            **params,
        )

    def _request(self, prompt: str, stream: bool = False, **params: Any) -> Response:
        payload_input = self._input_with(prompt)
        return self.client.create(
            payload_input,
            model=self.model or params.pop("model", None),
            instructions=params.pop("instructions", None) or self.instructions,
            store=self.store,
            **params,
        )

    def _input_with(self, prompt: str) -> List[InputItem]:
        if not isinstance(prompt, str) or not prompt.strip():
            raise ConfigurationError("prompt must be a non-empty string")
        return self.items + _normalize_input(prompt)

    def _record_user(self, prompt: str) -> None:
        self._record({"type": "message", "role": "user", "content": prompt})

    def _record(self, item: InputItem) -> None:
        self.items.append(item)
        if self.max_turns and len(self.items) > self.max_turns * 2:
            del self.items[: len(self.items) - self.max_turns * 2]


def send_prompt(prompt: str, **params: Any) -> str:
    """One-shot convenience: send a private prompt, return the reply text."""
    client_params = {key: params.pop(key) for key in ("api_key", "base_url", "timeout", "max_retries", "store") if key in params}
    return OpenAIClient(**client_params).complete(prompt, **params)


def stream_prompt(prompt: str, **params: Any) -> Iterator[str]:
    """One-shot convenience: stream a private prompt'"'s reply as text deltas.\"\"\"
    client_params = {key: params.pop(key) for key in (\"api_key\", \"base_url\", \"timeout\", \"max_retries\", \"store\") if key in params}
    client = OpenAIClient(**client_params)
    return client.stream_text(prompt, **params)


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog=\"openai_client.py\",
        description=\"Send private text prompts to the OpenAI Responses API (standard library only).\",
        epilog=\"Responses are not stored by OpenAI unless --store is given. \"
        \"Nothing is written to disk by this tool.\",
    )
    parser.add_argument(\"prompt\", nargs=\"*\", help=\"prompt text, or '-' to read stdin\")
    parser.add_argument(\"--model\", help=f\"model id (default: "'$OPENAI_MODEL or {DEFAULT_MODEL})")
    parser.add_argument("--system", "--instructions", dest="instructions", help="system instructions")
    parser.add_argument("--temperature", type=float)
    parser.add_argument("--max-output-tokens", type=int)
    parser.add_argument("--reasoning-effort", choices=["minimal", "low", "medium", "high"])
    parser.add_argument("--stream", action="store_true", help="stream output text deltas")
    parser.add_argument("--json", action="store_true", help="print the raw response JSON")
    parser.add_argument("--chat", action="store_true", help="interactive in-memory session")
    parser.add_argument("--store", action="store_true", help="let OpenAI store the response (default: private)")
    parser.add_argument("--timeout", type=float, default=DEFAULT_TIMEOUT)
    parser.add_argument("--max-retries", type=int, default=DEFAULT_MAX_RETRIES)
    parser.add_argument("--base-url", help=f"API root (default: $OPENAI_BASE_URL or {DEFAULT_BASE_URL})")
    parser.add_argument("--list-models", action="store_true", help="verify credentials and exit")
    parser.add_argument("-v", "--verbose", action="store_true", help="print latency and token usage to stderr")
    return parser


def _client_from_args(args: argparse.Namespace) -> OpenAIClient:
    return OpenAIClient(
        base_url=args.base_url,
        model=args.model,
        timeout=args.timeout,
        max_retries=args.max_retries,
        store=args.store,
    )


def _request_params(args: argparse.Namespace) -> Dict[str, Any]:
    params: Dict[str, Any] = {"instructions": args.instructions}
    if args.temperature is not None:
        params["temperature"] = args.temperature
    if args.max_output_tokens is not None:
        params["max_output_tokens"] = args.max_output_tokens
    if args.reasoning_effort:
        params["reasoning_effort"] = args.reasoning_effort
    return params


def _read_prompt(argv_prompt: Sequence[str]) -> str:
    joined = " ".join(part for part in argv_prompt if part != "-").strip()
    if "-" in argv_prompt or not joined:
        if sys.stdin.isatty() and not joined:
            raise ConfigurationError("no prompt given: pass it as an argument, pipe it in, or use --chat")
        piped = sys.stdin.read().strip()
        joined = f"{joined}'"\\n{piped}\".strip() if joined else piped
    if not joined:
        raise ConfigurationError(\"prompt is empty\")
    return joined


def _run_chat(client: OpenAIClient, args: argparse.Namespace) -> int:
    conversation = Conversation(client, model=args.model, instructions=args.instructions, store=args.store)
    print(
        \"Private chat: transcript stays in memory only, responses are not stored \"
        \"server-side unless --store was given.\\nCommands: /system TEXT, /clear, /exit\",
        file=sys.stderr,
    )
    while True:
        try:
            prompt = input(\"you> \").strip()
        except (EOFError, KeyboardInterrupt):
            print(file=sys.stderr)
            break
        if not prompt:
            continue
        if prompt.startswith(\"/\"):
            command, _, rest = prompt.partition(\" \")
            name = command.lower()
            if name in (\"/exit\", \"/quit\"):
                break
            if name == \"/clear\":
                conversation.clear()
                print(\"transcript cleared\", file=sys.stderr)
                continue
            if name == \"/system\":
                conversation.instructions = rest.strip() or None
                print(\"instructions updated\", file=sys.stderr)
                continue
            print(f\"unknown command: {command}\", file=sys.stderr)
            continue
        started = time.monotonic()
        try:
            if args.stream:
                print(\"ai> \", end=\"\", flush=True)
                for delta in conversation.stream(prompt):
                    print(delta, end=\"\", flush=True)
                print()
            else:
                print(f\"ai> {conversation.send(prompt)}\")
        except OpenAIError as exc:
            print(f\"error: {exc}\", file=sys.stderr)
            continue
        if args.verbose:
            usage = conversation.last_usage
            print(
                f\"[{time.monotonic() - started:.2f}s | in {usage.input_tokens} \"
                f\"out {usage.output_tokens} total {usage.total_tokens}]\",
                file=sys.stderr,
            )
    conversation.clear()
    return 0


def _run_once(client: OpenAIClient, args: argparse.Namespace, prompt: str) -> int:
    params = _request_params(args)
    started = time.monotonic()
    if args.stream:
        usage_line: List[str] = []
        for event in client.stream(prompt, **params):
            if event.type == \"response.output_text.delta\":
                sys.stdout.write(event.delta)
                sys.stdout.flush()
            elif event.type in (\"response.completed\", \"response.incomplete\"):
                final = event.response
                if final is not None and args.verbose:
                    usage_line.append(
                        f\"[{time.monotonic() - started:.2f}s | in {final.usage.input_tokens} \"
                        f\"out {final.usage.output_tokens} total {final.usage.total_tokens}]\"
                    )
                if args.json and final is not None:
                    sys.stdout.write(json.dumps(final.raw, indent=2, ensure_ascii=False) + \"\\n\")
        print()
        for line in usage_line:
            print(line, file=sys.stderr)
        return 0

    response = client.create(prompt, **params)
    if args.json:
        print(json.dumps(response.raw, indent=2, ensure_ascii=False))
    else:
        print(response.text)
    if args.verbose:
        print(
            f\"[{time.monotonic() - started:.2f}s | id {response.id or 'n/a'} | status {response.status or 'n/a'} \"
            f\"| in {response.usage.input_tokens} out {response.usage.output_tokens} \"
            f\"total {response.usage.total_tokens}]\",
            file=sys.stderr,
        )
    response.raise_for_status()
    return 0


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = _build_parser().parse_args(argv)
    try:
        client = _client_from_args(args)
        if args.list_models:
            models = client.list_models()
            print(f\"{len(models)} model(s) available to this key:\")
            for item in models:
