def _prepare(self, payload: Dict[str, Any]) -> urllib.request.Request:
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    headers = dict(self.default_headers)
    headers["Content-Type"] = "application/json"
    headers["Accept"] = "text/event-stream" if payload.get("stream") else "application/json"
    headers["Authorization"] = f"Bearer {self.api_key}"
    return urllib.request.Request(self.responses_url, data=body, headers=headers, method="POST")

def _open(self, payload: Dict[str, Any]) -> Any:
    """Send ``payload`` with retries, returning an open HTTP response."""
    attempt = 0
    while True:
        request = self._prepare(payload)
        try:
            return self._opener.open(request, timeout=self.timeout)
        except urllib.error.HTTPError as exc:
            body_text = _read_body(exc)
            if exc.code in RETRYABLE_STATUS_CODES and attempt < self.max_retries:
                delay = _retry_after_seconds(exc.headers)
                self._sleep(delay, attempt)
                attempt += 1
                continue
            raise _status_error(exc.code, exc.headers, body_text) from None
        except socket.timeout as exc:
            if attempt < self.max_retries:
                self._sleep(None, attempt)
                attempt += 1
                continue
            raise APITimeoutError(f"timed out after {self.timeout:g}s") from exc
        except (urllib.error.URLError, TimeoutError, ConnectionError, OSError, http.client.HTTPException) as exc:
            if isinstance(exc, urllib.error.HTTPError):
                raise
            reason = getattr(exc, "reason", exc)
            if isinstance(reason, socket.timeout):
                if attempt < self.max_retries:
                    self._sleep(None, attempt)
                    attempt += 1
                    continue
                raise APITimeoutError(f"timed out after {self.timeout:g}s") from exc
            if attempt < self.max_retries:
                self._sleep(None, attempt)
                attempt += 1
                continue
            raise APIConnectionError(f"could not reach {self.base_url}: {reason}") from exc

def _sleep(self, retry_after: Optional[float], attempt: int) -> None:
    delay = retry_after if retry_after is not None else min(8.0, 0.5 * (2**attempt))
    time.sleep(max(0.0, delay))

