def stream(self, input: Input, **params: Any) -> Iterator[StreamEvent]:
    """Yield :class:`StreamEvent` objects for a streaming request."""
    payload = self.build_payload(input, stream=True, **params)
    stream = self._open(payload)
    try:
        for event_name, data_text in _iter_sse(stream):
            if data_text.strip() == "[DONE]":
                break
            try:
                data = json.loads(data_text)
            except ValueError:
                continue
            if not isinstance(data, dict):
                continue
            event_type = str(data.get("type") or event_name)
            yield StreamEvent(type=event_type, event=event_name, data=data)
            if event_type in TERMINAL_STREAM_EVENTS:
                if event_type == "error":
                    error = data.get("error") or data
                    raise APIStatusError(
                        str(error.get("message") or "stream failed"),
                        error_type=error.get("type"),
                        code=error.get("code"),
                        body=data,
                    )
                break
    finally:
        try:
            stream.close()
        except Exception:
            pass

